// Define ListNode
typedef struct ListNode {
    int val;
    struct ListNode* next;
} ListNode;

// Helper to create a new node
ListNode* newNode(int v) {
    ListNode* n = (ListNode*)malloc(sizeof(ListNode));
    n->val = v; n->next = NULL; return n;
}

// Implement addTwoNumbers: returns head of new list
ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
    ListNode dummy; dummy.next = NULL;
    ListNode* cur = &dummy;
    int carry = 0;
    while (l1 != NULL || l2 != NULL || carry) {
        int x = l1 ? l1->val : 0;
        int y = l2 ? l2->val : 0;
        int sum = x + y + carry;
        carry = sum / 10;
        cur->next = newNode(sum % 10);
        cur = cur->next;
        if (l1) l1 = l1->next;
        if (l2) l2 = l2->next;
    }
    return dummy.next;
}

